348	\begin{definition}[Question distribution of the Pauli basis test]\label{def:pauli-question-distribution}
349		\uses{def:admissible, def:ld-question-distribution, def:ms-game, def:cl-func, def:cl-dist, def:graph-distribution}
350		% Admissibility of the full tuple is required here, not only the divisibility m | q:
351		% the source parametrizes the Pauli basis test by the tuple qldparams introduced
352		% together with Definition def:admissible (references/qpbt-paper/
353		% 08_classical_and_quantum_low_degree_tests.tex:958-1075), and both the fixed binary
354		% identification of F_q used by the map chi and the trace tr in eq:gamma-value
355		% require q to be a power of 2.
356		The game $\mathfrak{G}^{\mathrm{Pauli}}$ (also $\mathfrak{G}^{\mathrm{Pauli}}_{\mathsf{qldparams}}$) is parametrized by an admissible tuple $\mathsf{qldparams} = (q,m,d)$ (Definition~\ref{def:admissible}): admissibility makes $q$ a power of $2$, so that the field $\F_q$, its fixed identification with binary strings (Chapter~\ref{chap:qpbt-algebra}), and the trace $\tr\colon \F_q \to \F_2$ used by the win predicate below are defined, and it provides the divisibility $m \mid q$ required by the index map $\chi$ of Definition~\ref{def:ld-question-distribution}. The question type set is
357		\begin{equation}
358			\label{eq:pauli-type}
359			\mathcal T^{\mathrm{pauli}} = \bigl( \{\mathsf{Point}, \mathsf{ALine}, \mathsf{DLine}, \mathsf{Pauli}, \mathsf{Pair}\} \times \{X,Z\} \bigr) \cup \mathcal T^{\mathrm{ms}} \cup \{\mathsf{Pair}\}\;,
360		\end{equation}
361		where $\mathcal T^{\mathrm{ms}}$ is the type set of the Magic Square game (Definition~\ref{def:ms-game}).
362	
363		The ambient space is $V^{\mathrm{pauli}} = (\F_q^m)^2 \times \F_q \times \F_q^m \times (\F_q)^2$, decomposed into the register subspaces $V_X, V_Z$ (each $m$-dimensional over $\F_q$), $V_I$ ($1$-dimensional), $V_V$ ($m$-dimensional), and $V_{R_X}, V_{R_Z}$ ($1$-dimensional each); elements of $V^{\mathrm{pauli}}$ are written $(u_X, u_Z, s, v, r_X, r_Z)$. For each type $t \in \mathcal T^{\mathrm{pauli}}$ define a CL function $L_t\colon V^{\mathrm{pauli}} \to V^{\mathrm{pauli}}$ as follows, where $L_{\mathsf{Point}}, L_{\mathsf{ALine}}, L_{\mathsf{DLine}}$ are the CL functions of Definition~\ref{def:ld-question-distribution}:
364		\begin{enumerate}
365			\item for $W \in \{X,Z\}$, $L_{(\mathsf{Point},W)}(u_X,u_Z,s,v,r_X,r_Z) = L_{\mathsf{Point}}(u_W,s,v)$, a $1$-level CL function, where the range $V_W \oplus V_I \oplus V_V$ of $L_{\mathsf{Point}}$ is embedded in $V^{\mathrm{pauli}}$ in the natural way (the same convention applies in items~2 and~3);
366			\item for $W \in \{X,Z\}$, $L_{(\mathsf{ALine},W)}(u_X,u_Z,s,v,r_X,r_Z) = L_{\mathsf{ALine}}(u_W,s,v)$, a $2$-level CL function;
367			\item for $W \in \{X,Z\}$, $L_{(\mathsf{DLine},W)}(u_X,u_Z,s,v,r_X,r_Z) = L_{\mathsf{DLine}}(u_W,s,v)$, a $3$-level CL function;
368			\item for $t \in \mathcal T^{\mathrm{ms}} \cup \{\mathsf{Pair}, (\mathsf{Pair},X), (\mathsf{Pair},Z)\}$, $L_t(u_X,u_Z,s,v,r_X,r_Z) = (u_X,u_Z,0,0,r_X,r_Z)$, the $1$-level CL function projecting onto $V_X \oplus V_Z \oplus V_{R_X} \oplus V_{R_Z}$;
369			\item for $W \in \{X,Z\}$, $L_{(\mathsf{Pauli},W)} = 0$, the identically zero ($0$-level) CL function.
370		\end{enumerate}
371		The maps $L_{(\mathsf{Point},W)}$, $L_{(\mathsf{ALine},W)}$, $L_{(\mathsf{DLine},W)}$ act as the zero function on $V_{\overline W} \oplus V_{R_X} \oplus V_{R_Z}$, where $\overline W$ denotes the basis other than $W$.
372	
373		The \emph{type graph} $G^{\mathrm{pauli}}$ has vertex set $\mathcal T^{\mathrm{pauli}}$ and the following edges: all $18$ edges of the Magic Square type graph $G^{\mathrm{ms}}$ (Definition~\ref{def:ms-game}); the edges
374		\begin{align*}
375			&(\mathsf{ALine},X) \,\text{---}\, (\mathsf{Point},X)\;, &&(\mathsf{DLine},X) \,\text{---}\, (\mathsf{Point},X)\;, &&(\mathsf{Point},X) \,\text{---}\, (\mathsf{Pauli},X)\;,\\
376			&(\mathsf{ALine},Z) \,\text{---}\, (\mathsf{Point},Z)\;, &&(\mathsf{DLine},Z) \,\text{---}\, (\mathsf{Point},Z)\;, &&(\mathsf{Point},Z) \,\text{---}\, (\mathsf{Pauli},Z)\;,\\
377			&(\mathsf{Point},X) \,\text{---}\, \mathsf{Variable}_1\;, &&(\mathsf{Point},Z) \,\text{---}\, \mathsf{Variable}_5\;, &&\\
378			&(\mathsf{Point},X) \,\text{---}\, (\mathsf{Pair},X)\;, &&(\mathsf{Pair},X) \,\text{---}\, \mathsf{Pair}\;, &&\\
379			&(\mathsf{Point},Z) \,\text{---}\, (\mathsf{Pair},Z)\;, &&(\mathsf{Pair},Z) \,\text{---}\, \mathsf{Pair}\;; &&
380		\end{align*}
381		and, in addition, a self-loop at every vertex.
382	
383		% The type pair is drawn from the graph distribution of Definition
384		% def:graph-distribution, matching the source's formal definition
385		% (references/qpbt-paper/07_types.tex:84-93 together with
386		% references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:1115-1120).
387		% Sampling an undirected edge uniformly and then ordering its
388		% endpoints uniformly would be a different distribution here: it gives each self-loop
389		% twice the relative mass of an oriented non-loop pair, and G^pauli has a self-loop
390		% at every vertex.
391		The question distribution of $\mathfrak{G}^{\mathrm{Pauli}}$ is the typed CL distribution on $\mathcal T^{\mathrm{pauli}} \times V^{\mathrm{pauli}} \times \mathcal T^{\mathrm{pauli}} \times V^{\mathrm{pauli}}$ obtained by sampling the type pair $(t_{\mathrm A}, t_{\mathrm B})$ from the graph distribution $\mu_{G^{\mathrm{pauli}}}$ of Definition~\ref{def:graph-distribution}, that is, uniformly at random among all ordered pairs of types whose underlying unordered pair $\{t_{\mathrm A}, t_{\mathrm B}\}$ is an edge of $G^{\mathrm{pauli}}$, self-loops included; sampling $z \in V^{\mathrm{pauli}}$ uniformly at random; and setting $x_w = L_{t_w}(z)$ for $w \in \{\mathrm A,\mathrm B\}$. Explicitly, if $z = (u_X,u_Z,s,v,r_X,r_Z)$, then a player whose type is $(\mathsf{Point},W)$ receives $u_W$; a player whose type is $(\mathsf{ALine},W)$ receives $(u_0, s)$ with $u_0 = L^{\mathrm{Ln}}_{e_i}(u_W)$ and $i = \chi(s)$; a player whose type is $(\mathsf{DLine},W)$ receives $(u_0, s, v')$ with $i = \chi(s)$, $v' = \pi_{i-1}(v)$, and $u_0 = L^{\mathrm{Ln}}_{v'}(u_W)$; a player whose type lies in $\mathcal T^{\mathrm{ms}} \cup \{\mathsf{Pair}, (\mathsf{Pair},X), (\mathsf{Pair},Z)\}$ receives $(u_X, u_Z, r_X, r_Z)$; and a player whose type is $(\mathsf{Pauli},W)$ receives $0$.
392	\end{definition}
