 76	\begin{lemma}\label{lem:dlnf}
 77		\lean{MIPStarRE.QPBT.dLinePointDist_point_marginal_uniform, MIPStarRE.QPBT.dLinePointDist_mem_line, MIPStarRE.QPBT.dLinePointDist_prefix_zero}
 78		\leanok
